func HasAssigneeWith(preds ...predicate.Usuario) predicate.MensagemContato {
	return predicate.MensagemContato(func(s *sql.Selector) {
		step := newAssigneeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MensagemContato) predicate.MensagemContato {
	return predicate.MensagemContato(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MensagemContato) predicate.MensagemContato {
	return predicate.MensagemContato(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MensagemContato) predicate.MensagemContato {
	return predicate.MensagemContato(sql.NotPredicates(p))
}
